from flask import Flask, Response, stream_with_context
from models import Order, LineItem, Customer
from sqlalchemy.orm import joinedload

app = Flask(__name__)

@app.route('/api/accounts/<int:account_id>/orders.csv')
def export_orders(account_id):
    def generate():
        yield 'Order ID,Product,Quantity,Customer Name,Email,Total\n'
        for order in Order.query\n            .filter_by(account_id=account_id)\n            .options(joinedload(Order.line_items), joinedload(Order.customer))\n            .yield_per(2000):\n
            for line_item in order.line_items:
                yield f"{order.id},{line_item.product},{line_item.quantity},{order.customer.name},{order.customer.email},{order.total}\n"

    return Response(stream_with_context(generate()), mimetype='text/csv')

if __name__ == '__main__':
    app.run()

from flask import stream_with_context, Response
from models import Order, LineItem, Customer
from sqlalchemy.orm import joinedload
import csv
import io

@stream_with_context
def generate_csv_export():
    orders = Order.query.options(
        joinedload(Order.customer),
        joinedload(Order.line_items)
    ).yield_per(100)

    output = io.StringIO()
    writer = csv.writer(output)
    writer.writerow(["Order ID", "Customer Name", "Item", "Quantity"])

    for order in orders:
        for item in order.line_items:
            writer.writerow([
                order.id,
                order.customer.name,
                item.product_name,
                item.quantity
            ])
        yield output.getvalue()
        output.seek(0)
        output.truncate(0)

@app.route('/export/orders.csv')
def export_orders():
    return Response(
        generate_csv_export(),
        mimetype='text/csv',
        headers={"Content-Disposition": "attachment;filename=orders.csv"}
    )
